import type { TreeCursor } from '@lezer/common';

export function isCompleteStatement(statementCursor: TreeCursor): boolean {
  let hasKey = false;
  let hasOperator = false;
  let hasValue = false;

  statementCursor.iterate((childNode) => {
    switch (childNode.name) {
      case 'FilterKey':
        hasKey = true;
        break;
      case 'ComparisonOperator':
        hasOperator = true;
        break;
      case 'ExistsOperator':
        hasOperator = true;
        hasValue = true;
        break;
      case 'FilterSimpleValue':
        hasValue = true;
        break;
    }
  });

  return hasKey && hasOperator && hasValue;
}
